// Boot loader: does in hardware what sim/boot.py boot_from_image() does,
// standing in for the boot ROM (not available) while the system is held
// in reset:
//   1. waits for a floppy in F0;
//   2. writes the state of a freshly built Python system to the load ports
//      (boot_defaults.svh, generated by tools/gen_boot_defaults.py), clears
//      wave memory, internal memory and `ext_sectors` of external memory;
//   3. reads F0's catalog (logical sector 0: 8-word entries name[4], start,
//      length, words, type; an all-zero entry ends it) and finds MONITOR and
//      .LD-6 (the first entries of those names that are not catalogs);
//   4. copies MONITOR to external memory sector 0, setting the processor
//      type in its configuration table to Model B (set_processor), and takes
//      MEM.SIZ from the same table (entry 16, in sectors);
//   5. copies the floppy slot of .LD-6 (its first 512 words) to
//      LOC.LOAD = MEM.SIZ - 1024;
//   6. sets R0 = 0 (staging sector), R1 = 0 (destination), R2 = MONITOR's
//      length, PC (R17) = LOC.LOAD + 4 (the loader's ECOPY entry) and
//      releases the CPU.
// The loader copies MONITOR to 0 and starts it; MONITOR's cold boot reads
// the rest from the floppy through D100 as on the real machine.
//
// State mode: when a state image is mounted (SD drive 2; written by
// tools/state_image.py, format there) it is loaded instead, after the
// defaults: its device and voice entries to the load ports, wave memory,
// internal memory, its external memory (whose size it gives) and the
// registers. This starts the real-time program (ORK-LM) from the state the
// simulator reaches with sim/rtp.py start_rtp(). A version 2 image also
// gives the CPU model (cpu_model, Model C/D state through the debug port),
// D57, the D51 device bits, and stores only the first S sectors of
// external memory: the rest is cleared (Release 5.3: tools/w0_image.py).
// Header word 35 (M16) locates the staged MONITOR's options word; with
// `mono` (OSD) the loader sets o#pvoice (0200) in it, and `pvoice` is that
// bit as loaded (mono voice cards, dev_poly). With `printer` (OSD, M21) it
// sets o#d40 (020) there and configuration word 19 (two words on) to the
// printer type IDS Prism (p#prism 12, shifted left 8: 006000), as
// sim/boot.py set_printer does.
//
// Progress and errors are written to the terminal display (msg_*).
module boot_loader (
    input  logic        clk,
    input  logic        rst,                // power-on / user reset: boot again
    input  logic        f0_present,
    input  logic        state_present,      // a state image is mounted (drive 2)
    input  logic [16:0] floppy_ext_sectors, // external memory for a floppy boot
    output logic [16:0] ext_sectors,        // external memory now (state image: its own)
    output logic [1:0]  cpu_model,          // 1 B (floppy boot, version 1), else the image's
    output logic [15:0] cpu_d57,
    output logic [15:0] term_bits,          // D51 device bits
    input  logic        mono,               // OSD: mono poly voice cards (set o#pvoice)
    output logic        pvoice,             // o#pvoice of the loaded options word
    input  logic        printer,            // OSD: a printer on D40 (set o#d40, word 19)
    output logic        cpu_rst,            // the system's reset (load ports live)
    output logic        error,

    output logic        ld_dev_we,
    output logic [2:0]  ld_dev_sel,
    output logic [12:0] ld_dev_addr,
    output logic [31:0] ld_dev_data,
    output logic        ld_voice_we,
    output logic [5:0]  ld_voice_addr,
    output logic [63:0] ld_voice_data,
    output logic        dbg_we,
    output logic [4:0]  dbg_addr,
    output logic [15:0] dbg_wdata,
    output logic        ld_mem_we,
    output logic [15:0] ld_mem_addr,
    output logic [15:0] ld_mem_data,

    output logic [25:0] fd_addr,            // SD image words (sd_floppy): {drive, block, word}
    output logic        fd_rd,
    input  logic [15:0] fd_rdata,
    input  logic        fd_ack,
    output logic [23:0] xm_addr,            // external memory words
    output logic        xm_wr,
    output logic [15:0] xm_wdata,
    input  logic        xm_ack,

    output logic        msg_valid,
    output logic [7:0]  msg_data
);
    `include "boot_defaults.svh"

    localparam logic [15:0] XPL_FIRST_WORD = 16'o100377;
    localparam logic [15:0] O_PROCT = 16'o003400;
    localparam logic [15:0] MODEL_B = 16'o000400;

    typedef enum logic [3:0] {
        B_WAIT, B_DEFAULTS, B_WAVE, B_MEM, B_XM, B_CAT, B_MON, B_LD, B_REGS, B_RUN, B_FAIL,
        B_SHDR, B_SENT, B_SWAVE, B_SMEM, B_SXM
    } state_t;
    state_t state;

    // ------------------------------------------------------------ messages
    // m_sel picks a string; the characters go out one per clock. Each is a
    // 64-character packed string (Verilog literal: first character highest).
    localparam logic [8*64-1:0] MSG0 = "\r\nInsert a Release L system floppy (e.g. 03-SYSTD) in F0\r\n";
    localparam logic [8*64-1:0] MSG1 = "Booting MONITOR from F0\r\n";
    localparam logic [8*64-1:0] MSG2 = "Boot failed: MONITOR or .LD-6 not in F0's catalog\r\n";
    localparam logic [8*64-1:0] MSG3 = "Boot failed: MONITOR is not a valid XPL program\r\n";
    localparam logic [8*64-1:0] MSG4 = "Loading the state image (S2)\r\n";
    localparam logic [8*64-1:0] MSG5 = "Boot failed: not a state image (tools/state_image.py)\r\n";
    localparam int MSG_LEN [6] = '{58, 25, 51, 49, 30, 55};
    function automatic logic [7:0] msg_char(input logic [2:0] m, input logic [6:0] i);
        logic [8*64-1:0] s;
        int len;
        case (m)
            3'd0: begin s = MSG0; len = MSG_LEN[0]; end
            3'd1: begin s = MSG1; len = MSG_LEN[1]; end
            3'd2: begin s = MSG2; len = MSG_LEN[2]; end
            3'd3: begin s = MSG3; len = MSG_LEN[3]; end
            3'd4: begin s = MSG4; len = MSG_LEN[4]; end
            default: begin s = MSG5; len = MSG_LEN[5]; end
        endcase
        // the literal is right-aligned: character k of a len-character
        // string is at byte len-1-k
        msg_char = int'(i) < len ? s[8*(len - 1 - int'(i)) +: 8] : 8'd0;
    endfunction
    logic [2:0] m_sel;
    logic [6:0] m_pos;
    logic       m_busy;
    wire  [7:0] m_c = msg_char(m_sel, m_pos);
    assign msg_valid = m_busy && m_c != 8'd0;
    assign msg_data  = m_c;

    // -------------------------------------------------------- bookkeeping
    logic [16:0] n;                 // general counter
    logic [23:0] xn;
    logic [15:0] ent [8];           // catalog entry being read
    logic        have_mon, have_ld;
    logic [15:0] mon_start, mon_len, mon_words, ld_start, ld_len, ld_words;
    logic [15:0] cfg, memsiz;
    logic [16:0] mon_n, ld_n;       // words to copy
    logic        fd_wait;           // a floppy read is in flight
    logic        cat_done;
    // state mode
    logic        smode;
    logic [19:0] wp;                // next word of the image
    logic [15:0] hw [36];           // header words 0-35
    logic [16:0] stored;            // external memory sectors in the image
    logic [15:0] n_ent;
    logic        pend_lo;           // second byte of a wave-memory word
    logic [7:0]  lo_byte;
    logic [12:0] lo_addr;
    wire  [19:0] wp_block = (wp + 20'd255) & ~20'd255;     // next block boundary

    // words in a catalog entry's file (tools/ned_disk.py file_words)
    function automatic logic [16:0] file_words(input logic [15:0] length, input logic [15:0] words);
        logic [16:0] nw;
        nw = words != 16'd0 ? {1'b0, words} : {length[8:0], 8'd0};
        if ((nw + 17'd255) >> 8 != {1'b0, length}) nw = {length[8:0], 8'd0};
        file_words = nw;
    endfunction

    // the packed names, low byte first in each word
    localparam logic [63:0] NAME_MONITOR = {16'h0052, 16'h4f54, 16'h494e, 16'h4f4d};  // "MONITOR"
    localparam logic [63:0] NAME_LD6     = {16'h0000, 16'h0036, 16'h2d44, 16'h4c2e};  // ".LD-6"
    wire [63:0] ent_name = {ent[3], ent[2], ent[1], ent[0]};
    wire        ent_file = ent[7] != 16'd6 && ent[7] != 16'd7;

    wire [16:0] loc_load = {memsiz[8:0], 8'd0} - 17'd1024;
    wire [81:0] def = boot_default(n[8:0]);
    // set_processor(program, "B"): the options word, configuration entry 17
    wire [15:0] mon_word = n >= 17'd2 && n == {1'b0, cfg} + 17'd17
                         ? (fd_rdata & ~O_PROCT) | MODEL_B : fd_rdata;

    always_ff @(posedge clk) begin
        ld_dev_we <= 1'b0;
        ld_voice_we <= 1'b0;
        dbg_we <= 1'b0;
        ld_mem_we <= 1'b0;
        if (rst) begin
            state <= B_WAIT;
            cpu_rst <= 1'b1;
            error <= 1'b0;
            m_busy <= 1'b0;
            m_sel <= 3'd0;
            m_pos <= 7'd0;
            fd_rd <= 1'b0;
            xm_wr <= 1'b0;
            fd_wait <= 1'b0;
            n <= '0;
            smode <= 1'b0;
            pend_lo <= 1'b0;
            ext_sectors <= floppy_ext_sectors;
            cpu_model <= 2'd1;
            cpu_d57 <= 16'd0;
            term_bits <= 16'o001000;
            pvoice <= 1'b0;
        end else begin
            if (m_busy) begin
                if (m_c == 8'd0) m_busy <= 1'b0;
                else m_pos <= m_pos + 7'd1;
            end

            case (state)
            B_WAIT: begin
                if (state_present) begin
                    m_sel <= 3'd4; m_pos <= 7'd0; m_busy <= 1'b1;
                    smode <= 1'b1;
                    n <= '0;
                    state <= B_DEFAULTS;
                end else if (f0_present) begin
                    m_sel <= 3'd1; m_pos <= 7'd0; m_busy <= 1'b1;
                    n <= '0;
                    state <= B_DEFAULTS;
                end else if (n == 17'd0) begin
                    m_sel <= 3'd0; m_pos <= 7'd0; m_busy <= 1'b1;
                    n <= 17'd1;                  // say it once
                end
            end

            B_DEFAULTS: begin
                case (def[81:80])
                    2'd0: begin
                        ld_dev_we <= 1'b1; ld_dev_sel <= def[79:77];
                        ld_dev_addr <= def[76:64]; ld_dev_data <= def[31:0];
                    end
                    2'd1: begin
                        ld_voice_we <= 1'b1; ld_voice_addr <= def[69:64]; ld_voice_data <= def[63:0];
                    end
                    default: begin
                        dbg_we <= 1'b1; dbg_addr <= def[68:64]; dbg_wdata <= def[15:0];
                    end
                endcase
                if (n == 17'(BOOT_DEFAULTS - 1)) begin
                    n <= '0;
                    wp <= '0;
                    state <= smode ? B_SHDR : B_WAVE;
                end else n <= n + 17'd1;
            end

            B_WAVE: begin                         // wave memory: 32 x 256 bytes
                ld_dev_we <= 1'b1; ld_dev_sel <= 3'd6; ld_dev_addr <= n[12:0]; ld_dev_data <= '0;
                if (n == 17'd8191) begin n <= '0; state <= B_MEM; end
                else n <= n + 17'd1;
            end

            B_MEM: begin
                ld_mem_we <= 1'b1; ld_mem_addr <= n[15:0]; ld_mem_data <= '0;
                if (n == 17'd65535) begin xn <= '0; state <= B_XM; end
                else n <= n + 17'd1;
            end

            B_XM: begin                           // clear external memory
                if (xm_wr && xm_ack) begin
                    xm_wr <= 1'b0;
                    xn <= xn + 24'd1;
                end else if (!xm_wr && !xm_ack) begin
                    if ({1'b0, xn} == {ext_sectors, 8'd0}) begin
                        n <= '0; have_mon <= 1'b0; have_ld <= 1'b0; cat_done <= 1'b0;
                        state <= B_CAT;
                    end else begin
                        xm_addr <= xn; xm_wdata <= '0; xm_wr <= 1'b1;
                    end
                end
            end

            B_CAT: begin                          // catalog: sector 0, 32 entries
                if (fd_rd && fd_ack) begin
                    fd_rd <= 1'b0;
                    ent[n[2:0]] <= fd_rdata;
                    fd_wait <= 1'b1;              // evaluate after the 8th word lands
                    n <= n + 17'd1;
                end else if (fd_wait) begin
                    fd_wait <= 1'b0;
                    if (n[2:0] == 3'd0) begin     // a whole entry
                        if (ent[0] == 0 && ent[1] == 0 && ent[2] == 0 && ent[3] == 0 &&
                            ent[4] == 0 && ent[5] == 0 && ent[6] == 0 && ent[7] == 0)
                            cat_done <= 1'b1;
                        else if (ent_file && ent_name == NAME_MONITOR && !have_mon) begin
                            have_mon <= 1'b1;
                            mon_start <= ent[4]; mon_len <= ent[5]; mon_words <= ent[6];
                        end else if (ent_file && ent_name == NAME_LD6 && !have_ld) begin
                            have_ld <= 1'b1;
                            ld_start <= ent[4]; ld_len <= ent[5]; ld_words <= ent[6];
                        end
                    end
                end else if (!fd_rd && !fd_ack) begin
                    if (cat_done || n == 17'd256) begin
                        if (have_mon && have_ld) begin
                            mon_n <= file_words(mon_len, mon_words);
                            ld_n <= file_words(ld_len, ld_words);
                            n <= '0;
                            state <= B_MON;
                        end else begin
                            m_sel <= 3'd2; m_pos <= 7'd0; m_busy <= 1'b1;
                            state <= B_FAIL;
                        end
                    end else begin
                        fd_addr <= {2'd0, 16'd0, n[7:0]};
                        fd_rd <= 1'b1;
                    end
                end
            end

            B_MON: begin                          // MONITOR -> external memory 0..
                if (fd_rd && fd_ack) begin
                    fd_rd <= 1'b0;
                    if (n == 17'd1) cfg <= fd_rdata;
                    if (n >= 17'd2 && n == {1'b0, cfg} + 17'd16) memsiz <= fd_rdata;
                    if (n == 17'd0 && fd_rdata != XPL_FIRST_WORD) begin
                        m_sel <= 3'd3; m_pos <= 7'd0; m_busy <= 1'b1;
                        state <= B_FAIL;
                    end else begin
                        xm_addr <= {7'd0, n}; xm_wdata <= mon_word; xm_wr <= 1'b1;
                    end
                end else if (xm_wr && xm_ack) begin
                    xm_wr <= 1'b0;
                    n <= n + 17'd1;
                end else if (!fd_rd && !fd_ack && !xm_wr && !xm_ack) begin
                    if (n == mon_n) begin
                        if (memsiz == 16'd0 || memsiz > 16'd256 || {1'b0, cfg} + 17'd17 >= mon_n) begin
                            m_sel <= 3'd3; m_pos <= 7'd0; m_busy <= 1'b1;
                            state <= B_FAIL;
                        end else begin
                            n <= '0;
                            state <= B_LD;
                        end
                    end else begin
                        fd_addr <= {2'd0, 16'(mon_start + 16'(n[16:8])), n[7:0]};
                        fd_rd <= 1'b1;
                    end
                end
            end

            B_LD: begin                           // .LD-6 floppy slot -> LOC.LOAD
                if (fd_rd && fd_ack) begin
                    fd_rd <= 1'b0;
                    ld_mem_we <= 1'b1;
                    ld_mem_addr <= loc_load[15:0] + n[15:0];
                    ld_mem_data <= fd_rdata;
                    n <= n + 17'd1;
                end else if (!fd_rd && !fd_ack) begin
                    if (n == ld_n || n == 17'd512) begin
                        n <= '0;
                        state <= B_REGS;
                    end else begin
                        fd_addr <= {2'd0, 16'(ld_start + 16'(n[16:8])), n[7:0]};
                        fd_rd <= 1'b1;
                    end
                end
            end

            B_REGS: if (smode) begin              // R0-R17 and the flags from the header
                dbg_we <= 1'b1;
                dbg_addr <= n[4:0];
                dbg_wdata <= n < 17'd17 ? hw[6'd8 + 6'(n[4:0])] : hw[6'd11 + 6'(n[4:0])];
                if (n == (hw[4] == 16'd2 ? 17'd23 : 17'd16)) state <= B_RUN;
                n <= n + 17'd1;
            end else begin
                dbg_we <= 1'b1;
                case (n[1:0])
                    2'd0: begin dbg_addr <= 5'd0;  dbg_wdata <= 16'd0; end       // staging sector
                    2'd1: begin dbg_addr <= 5'd1;  dbg_wdata <= 16'd0; end       // destination
                    2'd2: begin dbg_addr <= 5'd2;  dbg_wdata <= mon_n[15:0]; end // length
                    default: begin dbg_addr <= 5'd15; dbg_wdata <= loc_load[15:0] + 16'd4; end
                endcase
                if (n[1:0] == 2'd3) state <= B_RUN;
                n <= n + 17'd1;
            end


            // ------------------------------------------- state image (drive 2)
            // Each state fetches the image's words in order (wp); a word
            // arrives with fd_ack and is used at once.
            B_SHDR: begin                         // block 0: the header
                if (fd_rd && fd_ack) begin
                    fd_rd <= 1'b0;
                    if (wp < 20'd36) hw[wp[5:0]] <= fd_rdata;
                    wp <= wp + 20'd1;
                end else if (!fd_rd && !fd_ack) begin
                    if (wp == 20'd256) begin
                        if (hw[0] != 16'h5359 || hw[1] != 16'h4e43 || hw[2] != 16'h5354 ||
                            hw[3] != 16'h4154 || (hw[4] != 16'd1 && hw[4] != 16'd2) ||
                            hw[5] == 16'd0 || hw[5] > 16'd8192 ||
                            (hw[4] == 16'd2 && hw[7] > hw[5])) begin
                            m_sel <= 3'd5; m_pos <= 7'd0; m_busy <= 1'b1;
                            state <= B_FAIL;
                        end else begin
                            ext_sectors <= {1'b0, hw[5]};
                            stored <= {1'b0, hw[4] == 16'd2 ? hw[7] : hw[5]};
                            if (hw[4] == 16'd2) begin
                                cpu_model <= hw[25][1:0];
                                cpu_d57 <= hw[26];
                                term_bits <= hw[27];
                            end
                            n_ent <= hw[6];
                            n <= '0;
                            state <= B_SENT;
                        end
                    end else begin
                        fd_addr <= {2'd2, 4'd0, wp};
                        fd_rd <= 1'b1;
                    end
                end
            end

            B_SENT: begin                         // entries: 8 words each
                if (fd_rd && fd_ack) begin
                    fd_rd <= 1'b0;
                    ent[n[2:0]] <= fd_rdata;
                    fd_wait <= n[2:0] == 3'd7;
                    n <= n + 17'd1;
                    wp <= wp + 20'd1;
                end else if (fd_wait) begin       // the 8th word has landed
                    fd_wait <= 1'b0;
                    if (ent[0] == 16'd0) begin
                        ld_dev_we <= 1'b1; ld_dev_sel <= ent[1][2:0];
                        ld_dev_addr <= ent[2][12:0]; ld_dev_data <= {ent[6], ent[7]};
                    end else begin
                        ld_voice_we <= 1'b1; ld_voice_addr <= ent[2][5:0];
                        ld_voice_data <= {ent[4], ent[5], ent[6], ent[7]};
                    end
                end else if (!fd_rd && !fd_ack) begin
                    if (n[16:3] == n_ent[13:0]) begin
                        wp <= wp_block;
                        n <= '0;
                        state <= B_SWAVE;
                    end else begin
                        fd_addr <= {2'd2, 4'd0, wp};
                        fd_rd <= 1'b1;
                    end
                end
            end

            B_SWAVE: begin                        // wave memory: 4096 words, 2 bytes each
                if (fd_rd && fd_ack) begin
                    fd_rd <= 1'b0;
                    ld_dev_we <= 1'b1; ld_dev_sel <= 3'd6;
                    ld_dev_addr <= {n[11:0], 1'b0}; ld_dev_data <= {24'd0, fd_rdata[15:8]};
                    pend_lo <= 1'b1;
                    lo_addr <= {n[11:0], 1'b1}; lo_byte <= fd_rdata[7:0];
                    n <= n + 17'd1;
                    wp <= wp + 20'd1;
                end else if (pend_lo) begin
                    pend_lo <= 1'b0;
                    ld_dev_we <= 1'b1; ld_dev_sel <= 3'd6;
                    ld_dev_addr <= lo_addr; ld_dev_data <= {24'd0, lo_byte};
                end else if (!fd_rd && !fd_ack) begin
                    if (n == 17'd4096) begin
                        n <= '0;
                        state <= B_SMEM;
                    end else begin
                        fd_addr <= {2'd2, 4'd0, wp};
                        fd_rd <= 1'b1;
                    end
                end
            end

            B_SMEM: begin                         // internal memory
                if (fd_rd && fd_ack) begin
                    fd_rd <= 1'b0;
                    ld_mem_we <= 1'b1; ld_mem_addr <= n[15:0]; ld_mem_data <= fd_rdata;
                    n <= n + 17'd1;
                    wp <= wp + 20'd1;
                end else if (!fd_rd && !fd_ack) begin
                    if (n == 17'd65536) begin
                        xn <= '0;
                        state <= B_SXM;
                    end else begin
                        fd_addr <= {2'd2, 4'd0, wp};
                        fd_rd <= 1'b1;
                    end
                end
            end

            B_SXM: begin                          // external memory: stored, then zeros
                if (fd_rd && fd_ack) begin
                    fd_rd <= 1'b0;
                    xm_addr <= xn; xm_wdata <= fd_rdata; xm_wr <= 1'b1;
                    if (hw[35] != 16'd0 && xn == {8'd0, hw[35] - 16'd1}) begin
                        xm_wdata <= fd_rdata | (mono ? 16'o200 : 16'd0) | (printer ? 16'o20 : 16'd0);
                        pvoice <= fd_rdata[7] | mono;
                    end
                    if (hw[35] != 16'd0 && xn == {8'd0, hw[35] + 16'd1} && printer)
                        xm_wdata <= 16'o6000;
                    wp <= wp + 20'd1;
                end else if (xm_wr && xm_ack) begin
                    xm_wr <= 1'b0;
                    xn <= xn + 24'd1;
                end else if (!fd_rd && !fd_ack && !xm_wr && !xm_ack) begin
                    if ({1'b0, xn} == {ext_sectors, 8'd0}) begin
                        n <= '0;
                        state <= B_REGS;
                    end else if ({1'b0, xn} >= {stored, 8'd0}) begin
                        xm_addr <= xn; xm_wdata <= '0; xm_wr <= 1'b1;
                    end else begin
                        fd_addr <= {2'd2, 4'd0, wp};
                        fd_rd <= 1'b1;
                    end
                end
            end

            B_RUN: cpu_rst <= 1'b0;

            default: error <= 1'b1;               // B_FAIL: stay in reset
            endcase
        end
    end
endmodule
